    app.innerHTML = `${header(true)}${demoNote}<main id="main" class="booking-page container"><div class="flow-topline"><a class="subtle-link" href="index.html">Seu momento no + Beleza</a><button class="underlined" data-action="my-bookings">Meus agendamentos</button></div><nav class="stepper" aria-label="Etapas do agendamento">${['Serviço', 'Profissional', 'Data & hora', 'Seus dados'].map((label, i) => `<button class="step ${step === i + 1 ? 'current' : ''} ${step > i + 1 ? 'done' : ''}" data-action="step" data-step="${i + 1}" ${step < i + 1 ? 'disabled' : ''} ${step === i + 1 ? 'aria-current="step"' : ''}><span>${step > i + 1 ? icon('check', 14) : i + 1}</span>${label}</button>`).join('')}</nav><div class="booking-layout"><section class="booking-main enter">${[bookingServices, bookingPeople, bookingDate, bookingDetails][step - 1](state)}${step < 4 ? `<div class="flow-navigation">${step > 1 ? '<button class="subtle-link" data-action="back">Voltar</button>' : '<span class="small-note">Escolha um serviço para continuar.</span>'}<button class="button button-dark" data-action="next" ${step === 1 && !booking.serviceId || step === 3 && (!booking.date || !booking.time) ? 'disabled' : ''}>${step === 3 ? 'Continuar para meus dados' : 'Continuar'}</button></div>` : '<button class="subtle-link flow-back" data-action="back">Voltar para data e horário</button>'}</section>${summary(state)}</div></main><div class="flow-footer">${icon('lock', 14)} Suas escolhas são salvas automaticamente neste navegador. <a href="painel.html">Ver painel profissional</a></div>`;
    if (M.storageFailed()) toast('Armazenamento indisponível. Libere-o para salvar reservas.');
